import type BigNumber from "bignumber.js";
import type { ValidatedNEA } from "../Validated";
import type { ValueGreaterThanMaxNumberError, ValueLessThanMinNumberError, ValueNotNumericError } from "../ValidationErrors";
/**
 * Creates a validator that validates that the numeric value passed
 * in is in the range given. The minimum and maximum values
 * are inclusive.
 *
 * @internal
 */
export declare const numberRange: <T extends number | bigint | BigNumber>(minimum: T, maximum: T) => <U extends number | bigint | BigNumber>(value: U) => ValidatedNEA<ValueNotNumericError | ValueLessThanMinNumberError | ValueGreaterThanMaxNumberError, U>;
